package com.lineage.data.item_armor;

import com.lineage.data.executor.ItemExecutor;
import com.lineage.server.model.Instance.L1ItemInstance;
import com.lineage.server.model.Instance.L1PcInstance;
import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;

/**
 * 屬性守護之鍊
 * @author server
 *
 */
public class Sabot extends ItemExecutor {
	private static final Log _log = LogFactory.getLog(Sabot.class);

	private int _Rdmg;//觸發機率
	private int _rnd;//固定傷害
	private int _sEv_rnd;//動畫特效編號
	private int _gfxid;//動畫特效編號

	public static ItemExecutor get() {
		return new Sabot();
	}

	public void execute(int[] data, L1PcInstance pc, L1ItemInstance item) {
		try {
			if (item == null) {
				return;
			}

			if (pc == null) {
				return;
			}

			int el = item.getEnchantLevel();

			switch (data[0]) {
			case 0:
				pc.addRegistStone(-10);
				pc.set_Sabot(0, 0, 0);
				break;
			case 1:
				pc.addRegistStone(10);
				int _Ev_rnd = el * _sEv_rnd;
				int r = _rnd + _Ev_rnd;
				if (r > 1000){
					r = 1000;
				}
				pc.set_Sabot(_Rdmg, r, _gfxid);
				break;
			}
		} catch (Exception e) {
			_log.error(e.getLocalizedMessage(), e);
		}
	}

	public void set_set(String[] set) {
		try {
			_Rdmg = Integer.parseInt(set[1]);
		} catch (Exception e) {
		}
		try {
			_rnd = Integer.parseInt(set[2]);
		} catch (Exception e) {
		}
		try {
			_sEv_rnd = Integer.parseInt(set[3]);
		} catch (Exception e) {
		}
		try {
